tool_input.old_string:
.top-nav-arrow {
  width: 32px;
  height: 48px;
  padding: 0;
  border: 0;
  color: var(--menu-text-color, #fff);
  background: transparent;
  font-size: 18px;
  cursor: pointer;
}

tool_input.new_string:
.top-nav-arrow {
  width: 36px;
  height: 100%;
  padding: 0;
  border: 0;
  color: #fff;
  background: rgba(92, 151, 205, 0.74);
  font-size: 20px;
  cursor: pointer;
  transition: background-color 0.2s ease;
}
